3	import (
4		"errors"
5		"math"
6		"strconv"
7		"strings"
8	)
9	
10	// 本地资金库操作返回的可判定错误。其它错误（I/O、JSON 损坏等）以原文返回。
11	var (
12		// ErrInvalidAction 表示动作原文不符合 transfer:<账户>:<金额> 的格式。
13		ErrInvalidAction = errors.New("malformed action")
14		// ErrExecutionRejected 汇总执行资格类失败：时间未到、状态不符、
15		// 动作为空或格式错误、余额不足、计算溢出。具体原因见 Error()。
16		ErrExecutionRejected = errors.New("execution rejected")
17	)
