252		res, err := store.TallyVote(id, 200)
253		if err != nil {
254			t.Fatalf("tally: %v", err)
255		}
256		if res.Passed || res.ForWeight != 0 || res.AgainstWeight != 300 ||
257			res.Turnout != 300 || res.Quorum != 600 || res.TalliedAt != 200 {
