			in.Delegations = []Delegation{{From: "alice", To: "bob"}, {From: "bob", To: "alice"}}
		}, ErrInvalidProposal},
		{"delegation cycle length three", func(in *CreateVoteInput) {
			in.Delegations = []Delegation{{From: "alice", To: "bob"}, {From: "bob", To: "carol"}, {From: "carol", To: "alice"}}
